patch:
diff --git a/repro-no-loss-of-precision.js b/repro-no-loss-of-precision.js
new file mode 100644
index 0000000..9f00a26
--- /dev/null
+++ b/repro-no-loss-of-precision.js
@@ -0,0 +1,35 @@
+"use strict";
+
+/*
+ * Check: no-loss-of-precision must not report number literals that are exactly
+ * representable, such as `9.000e+3` (== 9000).
+ *
+ * Usage: node repro-no-loss-of-precision.js [literal ...]
+ * With no arguments it checks the literals from the bug report.
+ * Exits 1 if any given literal is reported, 0 otherwise.
+ */
+
+const { Linter } = require("./lib/api");
+
+const literals = process.argv.length > 2
+    ? process.argv.slice(2)
+    : ["9.000e+3", "9.000e3", "9.0000e4"];
+
+const linter = new Linter();
+let failed = false;
+
+for (const literal of literals) {
+    const messages = linter.verify(
+        `const test = ${literal};`,
+        [{ rules: { "no-loss-of-precision": "error" } }]
+    );
+
+    if (messages.length) {
+        failed = true;
+        console.error(`FAIL ${literal} (= ${Number(literal)}): ${messages[0].message}`);
+    } else {
+        console.log(`ok   ${literal}`);
+    }
+}
+
+process.exit(failed ? 1 : 0);
